export function total(values: number[]): number {
  return values.reduce((result, value) => result + value, 0);
}

export async function sendWithRetry(send: () => Promise<string>): Promise<string> {
  try {
    return await send();
  } catch (error) {
    return await send();
  }
}

export function lookup(email: string, getByEmail: (email: string) => string | undefined) {
  return getByEmail(email.trim().toLowerCase());
}

export async function saveSettings(settings: Record<string, string>, persist: (settings: Record<string, string>) => Promise<void>): Promise<void> {
  void persist(settings);
}
